    const xlsWilkins = fila ? ['Wilkins movilidad','Wilkins engrosamiento','Wilkins calcificación',
                               'Wilkins subvalvular','Score Wilkins total']
      .map(k => k + '=' + String(fila[k])).join(' · ') : '(sin fila)';
