  resetEA(); __t.set('vmax_ao','2.6');
  try { sincronizarEADesdeGlobal(); } catch (e) {}
  __t.set('ea_grado','severa');
  window.esqSevManual = window.esqSevManual || {}; window.esqSevManual.ea = true;
