                 esclero: entra('gftxt-esten-aortica', 'Esclerosis'),
                 /* Con el grado puesto de verdad: que no se corte. */
                 cortIM: cortado('gftxt-insuf-mitral'), cortEA: cortado('gftxt-esten-aortica'),
