  __t.nuevoEstudio(); abrir();
  const e7vacio = F();
  if (gg.estudioId) __t.reabrir(gg.estudioId);
  await new Promise(function (r) { setTimeout(r, 600); });
  abrir();
  const e7despues = F();
  await __t.borrar(gg.estudioId);

  /* ── (8) TODOS LOS GESTOS QUE PODRIAN DESINCRONIZARLOS ───────────────────────────────────── */
  const gestos = [];
