    const T   = (id) => { const e = EL(id); return e ? (e.textContent || '').trim() : 'NO EXISTE'; };
    const FN  = (n) => typeof window[n] === 'function';
    const S   = (id, v) => { try { __t.set(id, v); } catch (e) {} };
