    NUEVO();
    S('peso', '80'); S('talla', '180'); S('im_vc', '9'); S('ete_diam_anular', '30');
    S('ai_vol', '120'); S('ai_area', '28');
    try { if (FN('calcAI')) calcAI(); } catch (e) {}
