    const xDe = (t, k) => { const i = t.puntos.indexOf(k); return i < 0 ? NaN : t.puntoX[i] };
    const x1 = xDe(leerCard(), 'ai-vol'); cerrar();
    escena(Object.assign({}, BSA2, { ai_vol: '98' }), 'M'); abrir('ai-card');
