    const bd = (e, b2) => { const r = LL('aorNomoBanda', LL('aorNomoPara', e), b2);
      return (r && typeof r.lo === 'number') ? (r.lo.toFixed(3) + '|' + r.hi.toFixed(3)) : String(r); };
