  const _tipoLbl = (typeof VAB_TIPO_LBL === 'object' && VAB_TIPO_LBL) ? VAB_TIPO_LBL : null;
  const _tiposLbl= (typeof VAB_TIPOS_LBL === 'object' && VAB_TIPOS_LBL) ? VAB_TIPOS_LBL : null;
